SELECT A.PRODUCT_ID, A.TITLE, (SELECT IMAGE_URL FROM tb_product_image WHERE PRODUCT_ID = A.PRODUCT_ID AND REPRESENT = 1 LIMIT 1) AS IMAGE_URL, O.ORDER_ID, O.ORDER_NO, O.USER_NO, O.ORDER_STATUS, O.PAYMENT_STATUS, O.TOTAL_ITEM_AMOUNT, O.DELIVERY_FEE, O.DISCOUNT_AMOUNT, O.TOTAL_PAY_AMOUNT, DATE_FORMAT(O.ORDERED_AT, '%Y.%m.%d %H:%i') AS ORDERED_AT, O.PAID_AT, O.DELIVERY_COMPANY_CODE, (SELECT CODE_NM FROM op_code WHERE GROUP_ID = 'R010660' AND CODE = O.DELIVERY_COMPANY_CODE) AS DELIVERY_COMPANY_NM, O.TRACKING_NO, I.PRODUCT_NAME, I.UNIT_PRICE, I.QUANTITY FROM tb_product A INNER JOIN tb_order_items I ON A.PRODUCT_ID = I.PRODUCT_ID INNER JOIN tb_orders O ON I.ORDER_ID = O.ORDER_ID
